// Owner: data (wave-2 integration, 20 Nov 2026). Checks the wave-2 data (src/lib/data/wave2, GENERATED by
// research/wave2/build.py) wired into the catalogue like the expansion's: ids, SKILLS, COURSES, JOBS, GUIDES and the merged
// career families (../careers.ts). The same rules as ../expansion/expansion.test.ts: five requirements in roadmap order,
// prerequisites inside a field and never leading to a data-field skill, aliases that follow src/lib/data/skills.ts (none
// in two skills, none in the sample CV, no level word, no company's spelling), one course per star slot, one guide per
// skill (Coursera «paid»), and a knowledge base whose facts keep their links. No new job reaches 53% with the demo's
// sample CV, so the jobs list after the CV (demo step 6) does not move.
import { describe, expect, it } from "vitest";

import { cleanJobTitle, COMPANIES, COMPANY_TILES, COURSES, getGuide, JOBS, SAMPLE_CV_BODY, SKILLS } from "@/lib/data";
import { ADVANCED_WORDS, MIDDLE_WORDS } from "@/lib/brain/cv/local-analyser";
import { COMPANY_IDS, COURSE_IDS, FIELD_IDS, JOB_FIELD_IDS, JOB_IDS, SKILL_IDS } from "@/lib/ids";
import { findKeywords, normalizeText } from "@/lib/text/normalize";

import { CAREER_FAMILIES, CAREER_FAMILY_IDS, careersIndexForModel, ENTRY_ROUTES, knowledgeForModel } from "../careers";
import { COMPANY_LOGOS } from "../company-logos";
import { WAVE2_COURSE_IDS, WAVE2_COURSES } from "./courses";
import { WAVE2_GUIDES } from "./guides";
import { WAVE2_JOB_IDS, WAVE2_JOBS } from "./jobs";
import { WAVE2_CAREER_FAMILIES, WAVE2_ENTRY_ROUTES, WAVE2_FAMILY_IDS } from "./knowledge";
import { WAVE2_FIELDS, WAVE2_SKILL_IDS, WAVE2_SKILLS } from "./skills";

// ─── helpers (the same lenient reading as src/lib/data/data.test.ts and the expansion's test) ──────────────────────

function norm(text: string): string {
  return text
    .normalize("NFKC")
    .replace(/[ً-ٰٟـ‌-‏‪-‮]/g, "")
    .replace(/[أإآ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .toLowerCase();
}

function words(text: string): string[] {
  return norm(text)
    .split(/[^\p{L}\p{N}+#]+/u)
    .filter((w) => w.length > 0);
}

function readings(word: string): string[] {
  const out = new Set<string>([word]);
  const stripAl = (w: string) => (w.startsWith("ال") && w.length > 3 ? w.slice(2) : w);
  out.add(stripAl(word));
  if (word.startsWith("لل") && word.length > 3) out.add(word.slice(2));
  if (/^[وفبلك]/.test(word) && word.length > 2) {
    out.add(word.slice(1));
    out.add(stripAl(word.slice(1)));
  }
  return [...out];
}

function aliasOccurs(alias: string, textWords: readonly string[]): boolean {
  const aliasWords = words(alias).map((w) => (w.startsWith("ال") && w.length > 3 ? w.slice(2) : w));
  if (aliasWords.length === 0) return false;
  for (let i = 0; i + aliasWords.length <= textWords.length; i++) {
    const ok = aliasWords.every((aw, j) => {
      const tw = textWords[i + j];
      return tw !== undefined && readings(tw).includes(aw);
    });
    if (ok) return true;
  }
  return false;
}

const wordCount = (text: string) => text.trim().split(/\s+/).length;
const isUrl = (url: string) => /^https:\/\/[^\s]+$/.test(url);
const isDay = (day: string) => /^\d{4}-\d{2}-\d{2}$/.test(day);

const byId = new Map(SKILLS.map((s) => [s.id as string, s]));
const skill = (id: string) => {
  const s = byId.get(id);
  if (!s) throw new Error(`unknown skill ${id}`);
  return s;
};
const isNew = (id: string) => (WAVE2_SKILL_IDS as readonly string[]).includes(id);
function prereqsOf(id: string, seen: Set<string> = new Set()): Set<string> {
  for (const p of skill(id).prereqs) {
    if (seen.has(p)) continue;
    seen.add(p);
    prereqsOf(p, seen);
  }
  return seen;
}

const BARE_WORDS = ["تحليل", "بيانات", "تصميم", "مشروع", "إدارة", "كتابة", "تقارير", "تطوير", "تدريب", "مبيعات", "نظام", "عرض", "تقديم", "عمل", "فريق"];
const SAMPLE_SKILLS = ["excel", "sql", "statistics", "programming", "english", "communication", "presentation", "teamwork"];
/** The sample CV's stars (src/lib/engine/test-fixtures.ts SAMPLE_CV_SKILLS). */
const SAMPLE: Readonly<Record<string, number>> = { excel: 2, sql: 2, statistics: 1, programming: 1, english: 2, communication: 1, presentation: 1, teamwork: 1 };
const LESSONS_FOR_HOURS: Readonly<Record<number, number>> = { 6: 3, 8: 4, 10: 5, 12: 5, 14: 6, 16: 6 };
const NOT_NAJDI = ["الآن", "هذه", "لا أستطيع", "سوف", "لديك", "يمكنك", "ماذا", "إيش", "ايش", "دحين", "كدا", "عايز", "شو", "هلّق"];

// ─── fields and skills ──────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 2: fields and skills", () => {
  it("wires the nine new fields (before professional) and the 39 new skills into the ids and the catalogue", () => {
    expect(WAVE2_FIELDS).toHaveLength(9);
    for (const f of WAVE2_FIELDS) {
      expect((FIELD_IDS as readonly string[]).includes(f.id), f.id).toBe(true);
      expect((JOB_FIELD_IDS as readonly string[]).includes(f.id), f.id).toBe(true);
    }
    expect(FIELD_IDS[FIELD_IDS.length - 1]).toBe("professional");
    expect(WAVE2_SKILLS.map((s) => s.id)).toEqual([...WAVE2_SKILL_IDS]);
    expect(new Set(WAVE2_SKILL_IDS).size).toBe(39);
    for (const s of WAVE2_SKILLS) {
      expect((SKILL_IDS as readonly string[]).includes(s.id), s.id).toBe(true);
      expect(SKILLS.find((x) => x.id === s.id), s.id).toBe(s);
      expect(wordCount(s.description), s.id).toBeLessThan(15);
    }
  });

  it("keeps prerequisites inside the field and never lets a new skill lead to a data-field skill", () => {
    for (const s of WAVE2_SKILLS) for (const p of s.prereqs) expect(skill(p).field, `${s.id} → ${p}`).toBe(s.field);
    for (const s of SKILLS.filter((x) => x.field === "data")) {
      for (const p of prereqsOf(s.id)) expect(isNew(p), `${s.id} needs ${p}`).toBe(false);
    }
  });
});

// ─── aliases ────────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 2: aliases (rules of src/lib/data/skills.ts)", () => {
  it("gives every new skill an Arabic and an English alias, never a bare 9.2 word or a level word", () => {
    const bare = new Set(BARE_WORDS.flatMap((w) => [norm(w), norm(`ال${w}`)]));
    for (const s of WAVE2_SKILLS) {
      expect(s.aliases.some((a) => /[؀-ۿ]/.test(a)), s.id).toBe(true);
      expect(s.aliases.some((a) => /[A-Za-z]/.test(a)), s.id).toBe(true);
      for (const a of s.aliases) {
        expect(bare.has(norm(a.trim())), `${s.id}: ${a}`).toBe(false);
        expect(findKeywords(normalizeText(a), [...ADVANCED_WORDS, ...MIDDLE_WORDS]), `${s.id}: ${a}`).toEqual([]);
      }
    }
  });

  it("never gives the same alias to two skills (all 93) and never reuses a company's spelling", () => {
    const owner = new Map<string, string>();
    for (const s of SKILLS) {
      for (const a of s.aliases) {
        const key = norm(a.trim());
        expect(owner.get(key) ?? s.id, `${a} in ${s.id} and ${owner.get(key) ?? ""}`).toBe(s.id);
        owner.set(key, s.id);
      }
    }
    const spellings = new Set(COMPANIES.flatMap((c) => [...c.aliases, ...(c.aliasesAlone ?? [])]).map((a) => norm(a.trim())));
    for (const s of WAVE2_SKILLS) for (const a of s.aliases) expect(spellings.has(norm(a.trim())), `${s.id}: ${a}`).toBe(false);
  });

  it("finds no new alias in the sample CV, which still names exactly its eight skills", () => {
    const text = words(SAMPLE_CV_BODY);
    const normalized = SAMPLE_CV_BODY.split("\n").map((line) => normalizeText(line));
    for (const s of WAVE2_SKILLS) {
      expect(s.aliases.filter((a) => aliasOccurs(a, text)), s.id).toEqual([]);
      for (const line of normalized) expect(findKeywords(line, s.aliases), `${s.id} in «${line}»`).toEqual([]);
    }
    const named = SKILLS.filter((s) => s.aliases.some((a) => aliasOccurs(a, text))).map((s) => s.id);
    expect([...named].sort()).toEqual([...SAMPLE_SKILLS].sort());
  });
});

// ─── courses ────────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 2: courses", () => {
  it("has one course per new star slot, wired into COURSE_IDS and COURSES, 68 in all and 728 hours", () => {
    const expected = WAVE2_SKILLS.flatMap((s) => Array.from({ length: s.maxStars }, (_, i) => `c-${s.id}-${i + 1}`));
    expect(WAVE2_COURSES.map((c) => c.id)).toEqual(expected);
    expect([...WAVE2_COURSE_IDS]).toEqual(expected);
    for (const c of WAVE2_COURSES) {
      expect((COURSE_IDS as readonly string[]).includes(c.id), c.id).toBe(true);
      expect(COURSES.find((x) => x.id === c.id), c.id).toBe(c);
      expect(LESSONS_FOR_HOURS[c.hours], c.id).toBe(c.lessons.length);
      expect(c.description.split(/[.!؟]\s*/).filter((x) => x.trim().length > 0).length, c.id).toBe(2);
    }
    expect(WAVE2_COURSES).toHaveLength(68);
    expect(WAVE2_COURSES.reduce((sum, c) => sum + c.hours, 0)).toBe(728);
  });
});

// ─── jobs ───────────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 2: real jobs", () => {
  it("lists every job once, wired into JOB_IDS and JOBS, with syarah-financial ahead of every job outside design and marketing", () => {
    expect(WAVE2_JOBS.map((j) => j.id)).toEqual([...WAVE2_JOB_IDS]);
    expect(new Set(WAVE2_JOB_IDS).size).toBe(38);
    for (const j of WAVE2_JOBS) {
      expect((JOB_IDS as readonly string[]).includes(j.id), j.id).toBe(true);
      expect(JOBS.find((x) => x.id === j.id), j.id).toEqual({ ...j, title: cleanJobTitle(j.title) });
    }
    const later = WAVE2_JOBS.filter((j) => j.field !== "design" && j.field !== "marketing").map((j) => (JOB_IDS as readonly string[]).indexOf(j.id));
    expect(JOB_IDS.indexOf("syarah-financial-analyst-tamheer-riyadh")).toBeLessThan(Math.min(...later));
  });

  it("gives every job five distinct requirements within the skill's stars, in roadmap order, with the posting's evidence", () => {
    for (const j of WAVE2_JOBS) {
      expect(new Set(j.requirements.map((r) => r.skill)).size, j.id).toBe(5);
      j.requirements.forEach((r, i) => {
        expect(r.stars, `${j.id}: ${r.skill}`).toBeLessThanOrEqual(skill(r.skill).maxStars);
        expect((r.evidence ?? "").length, `${j.id}: ${r.skill}`).toBeGreaterThan(0);
        for (const p of prereqsOf(r.skill)) {
          const at = j.requirements.findIndex((x) => x.skill === p);
          if (at >= 0) expect(at, `${j.id}: ${p} before ${r.skill}`).toBeLessThan(i);
        }
      });
    }
  });

  it("is a real posting from the company's own page or ATS, never LinkedIn, Indeed or Bayt", () => {
    for (const j of WAVE2_JOBS) {
      expect(j.real, j.id).toBe(true);
      expect(j.source && isUrl(j.source.url), j.id).toBe(true);
      expect(j.source?.url ?? "", j.id).not.toMatch(/linkedin\.com|indeed\.|bayt\.com/);
      expect(isDay(j.source?.checkedAt ?? ""), j.id).toBe(true);
    }
  });

  it("keeps every new job under 53% with the demo's sample CV (the jobs list after the CV does not move)", () => {
    for (const j of WAVE2_JOBS) {
      const sixths = j.requirements.reduce((sum, r) => sum + (120 * Math.min(SAMPLE[r.skill] ?? 0, r.stars)) / r.stars, 0);
      expect(Math.round(sixths / 6), j.id).toBeLessThan(53);
    }
  });
});

// ─── guides ─────────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 2: guides", () => {
  it("has one guide per new skill with real, dated links, Coursera marked paid, a certificate block, served by getGuide", () => {
    expect(WAVE2_GUIDES.map((g) => g.skill)).toEqual([...WAVE2_SKILL_IDS]);
    for (const g of WAVE2_GUIDES) {
      expect(g.alternatives.length, g.skill).toBeLessThanOrEqual(2);
      for (const c of [g.topPick, ...g.alternatives]) {
        expect(isUrl(c.url) && isDay(c.checkedAt), `${g.skill}: ${c.url}`).toBe(true);
        if (c.url.includes("coursera.org")) expect(c.price, `${g.skill}: ${c.url}`).toBe("paid");
      }
      for (const p of g.people) expect(isUrl(p.url), `${g.skill}: ${p.name}`).toBe(true);
      for (const a of g.articles) expect(isUrl(a.url), `${g.skill}: ${a.url}`).toBe(true);
      expect(g.certification, g.skill).toBeDefined();
      expect(getGuide(g.skill), g.skill).toBe(g);
    }
    // CCP-KSA keeps its page's own location caveat (never shown as bookable from Saudi Arabia without it)
    const ccp = WAVE2_GUIDES.find((g) => g.skill === "medical-coding")?.certification;
    expect(ccp?.why ?? "").toContain("Only available in the U.S.");
  });
});

// ─── career families ────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 2: career families (merged in ../careers.ts)", () => {
  it("adds 18 families after the expansion's 16, and 6 entry routes", () => {
    expect(WAVE2_CAREER_FAMILIES.map((f) => f.id)).toEqual([...WAVE2_FAMILY_IDS]);
    // 34 with wave 2; wave 3 (../wave3) adds 7 after them
    expect(CAREER_FAMILY_IDS).toHaveLength(41);
    expect(CAREER_FAMILIES.map((f) => f.id)).toEqual([...CAREER_FAMILY_IDS]);
    expect(WAVE2_ENTRY_ROUTES).toHaveLength(6);
    expect(careersIndexForModel().split("\n")).toHaveLength(41);
  });

  it("names only existing skills, fields, jobs and entry routes, with links on every fact and Najdi bot lines", () => {
    const routes = new Set<string>(ENTRY_ROUTES.map((r) => r.id));
    for (const f of WAVE2_CAREER_FAMILIES) {
      for (const s of f.path.skills) expect(byId.has(s), `${f.id}: ${s}`).toBe(true);
      for (const fl of f.fields) expect((FIELD_IDS as readonly string[]).includes(fl), `${f.id}: ${fl}`).toBe(true);
      for (const j of f.jobs) expect((JOB_IDS as readonly string[]).includes(j), `${f.id}: ${j}`).toBe(true);
      for (const r of f.entryRoutes) expect(routes.has(r), `${f.id}: ${r}`).toBe(true);
      for (const e of f.employers) expect(isUrl(e.careersUrl) && isDay(e.checkedAt), `${f.id}: ${e.name}`).toBe(true);
      for (const c of f.certificates) expect(isUrl(c.url), `${f.id}: ${c.name}`).toBe(true);
      if (f.salary) expect(isUrl(f.salary.url) && f.salary.minSAR < f.salary.maxSAR, f.id).toBe(true);
      expect(f.botLines.length, f.id).toBeGreaterThanOrEqual(2);
      // a quoted name («اشترِ الآن وادفع لاحقًا», the BNPL category) is not the bot's own wording
      for (const line of [...f.botLines, f.what].map((l) => l.replace(/«[^»]*»/g, ""))) {
        for (const w of NOT_NAJDI) {
          expect(words(line).includes(norm(w)) || (w.includes(" ") && line.includes(w)), `${f.id}: «${w}» in «${line}»`).toBe(false);
        }
      }
    }
    for (const r of WAVE2_ENTRY_ROUTES) {
      expect(isUrl(r.url) && isDay(r.checkedAt), r.id).toBe(true);
      if (r.fits !== "all") for (const id of r.fits) expect((CAREER_FAMILY_IDS as readonly string[]).includes(id), `${r.id}: ${id}`).toBe(true);
    }
    expect(knowledgeForModel(["audit"])).toContain("CAREER audit «");
  });
});

// ─── companies ──────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 2: companies and logos (research/wave2/companies.json)", () => {
  it("knows the 69 new companies (the unverified ones by name only), their logos by name, and «مهارة» first on every new tile set", () => {
    // 107 with wave 2; wave 3 adds the 34 companies of its postings
    expect(COMPANY_IDS).toHaveLength(141);
    // (Riyadh Air's own board opened in wave 3, 21 Nov 2026: ../companies.ts CORRECTIONS)
    for (const id of ["bank-aljazira", "sipchem", "soudah", "flyadeal", "flynas", "saudia", "nhc"]) {
      const c = COMPANIES.find((x) => x.id === id);
      expect(c?.careersUrl, id).toBeNull();
      expect(c?.note ?? "", id).toContain("not verified");
    }
    for (const id of ["alinma", "mozn", "nahdi", "hmg", "mbc"]) expect(COMPANIES.find((x) => x.id === id)?.source, id).toBe("careers-page");
    expect(COMPANY_LOGOS["مصرف الإنماء"]).toBe("/logos/alinma.png");
    expect(COMPANY_LOGOS["Almosafer"]).toBe("/logos/almosafer.svg");
    const tiles: Readonly<Record<string, readonly string[]>> = COMPANY_TILES;
    for (const f of WAVE2_FIELDS) expect(tiles[f.id]?.[0], f.id).toBe("maharah");
  });
});
